def balanced(s):
    pairs = {")": "(", "]": "[", "}": "{"}
    stack = []
    i = 0

    while i < len(s):
        ch = s[i]

        if ch == '"':
            i += 1
            while i < len(s) and s[i] != '"':
                if s[i] == "\\":
                    i += 1
                i += 1
            if i >= len(s):
                return False
        elif ch in "([{":
            stack.append(ch)
        elif ch in ")]}":
            if not stack or stack.pop() != pairs[ch]:
                return False

        i += 1

    return not stack
